alter table agni_usage_events enable row level security;
-- Device attribution (2026-10-31): see agni_reserve's p_device_subject.
alter table agni_usage_events add column if not exists device_subject text;
alter table agni_actions add column if not exists device_subject text;
create index if not exists agni_usage_events_device on agni_usage_events (subject_id, device_subject);
create index if not exists agni_usage_events_open on agni_usage_events (created_at) where status = 'reserved';
create index if not exists agni_usage_events_day on agni_usage_events (day);

-- MARK: - The emergency ceiling

-- Operator-set. Changing a value here takes effect from the next UTC day, or
-- immediately by updating today's agni_budget_days.ceiling_usd by hand.
create table if not exists agni_budget_config (
  id                        integer primary key default 1 check (id = 1),
  -- The ceiling with no paying subscribers at all.
  base_ceiling_usd          numeric not null default 25,
  -- Added per active, verified, Production, non-trial subscription. About a
  -- day of the paid allowance ($2.50/month is $0.083/day), so paying users
  -- grow the ceiling and nobody else can.
  per_paid_subscriber_usd   numeric not null default 0.10,
  -- Never exceeded without an operator raising it.
  hard_max_ceiling_usd      numeric not null default 150,
  -- The most the ceiling may rise from one day to the next.
  max_daily_growth          numeric not null default 1.5,
  -- Free and legacy AI stop at this share of the ceiling, trial at the next,
  -- paid and beta only at the ceiling itself.
  free_share                numeric not null default 0.5,
  trial_share               numeric not null default 0.8,
  -- The shared-token path's own daily ceiling, while it exists.
  legacy_day_cap_usd        numeric not null default 10,
  -- Sandbox (TestFlight, App Review) has its own daily ceiling. Its spend is
  -- real and counts toward the day's total; it never raises the ceiling.
  sandbox_day_cap_usd       numeric not null default 5,
  -- The voice companion PROTOTYPE: its own daily ceiling across everyone, so
  -- a development feature can never eat into what subscribers pay for.
  companion_day_cap_usd     numeric not null default 2,
  updated_at                timestamptz not null default now()
);
alter table agni_budget_config enable row level security;
alter table agni_budget_config add column if not exists sandbox_day_cap_usd numeric not null default 5;
alter table agni_budget_config add column if not exists companion_day_cap_usd numeric not null default 2;
insert into agni_budget_config (id) values (1) on conflict (id) do nothing;

create table if not exists agni_budget_days (
  day              date primary key,
  ceiling_usd      numeric not null,
  paid_subscribers integer not null default 0,
  free_usd         numeric(12,6) not null default 0,
  trial_usd        numeric(12,6) not null default 0,
  paid_usd         numeric(12,6) not null default 0,
  beta_usd         numeric(12,6) not null default 0,
  legacy_usd       numeric(12,6) not null default 0,
  sandbox_usd      numeric(12,6) not null default 0,
  companion_usd    numeric(12,6) not null default 0,
  alerted_level    integer not null default 0,     -- highest of 50, 80, 100 already alerted
  degraded_tiers   text[] not null default '{}'
);
alter table agni_budget_days enable row level security;
alter table agni_budget_days add column if not exists sandbox_usd numeric(12,6) not null default 0;
alter table agni_budget_days add column if not exists companion_usd numeric(12,6) not null default 0;

create table if not exists agni_alerts (
  id      bigserial primary key,
  at      timestamptz not null default now(),
  kind    text not null,
  detail  jsonb
);
alter table agni_alerts enable row level security;

-- App Store Server Notifications already processed, so a redelivery is a no-op.
create table if not exists agni_store_notifications (
  notification_uuid        text primary key,
  notification_type        text,
  subtype                  text,
  original_transaction_id  text,
  signed_date              timestamptz,
  received_at              timestamptz not null default now()
);
alter table agni_store_notifications enable row level security;

-- Coarse per-IP windows for unauthenticated surfaces: attestation challenges
-- and registration, and the legacy token. The IP is hashed with a server salt
-- before it gets here.
create table if not exists agni_ip_windows (
  bucket        text not null,
  ip_hash       text not null,
  window_start  timestamptz not null default now(),
  count         integer not null default 0,
  primary key (bucket, ip_hash)
);
alter table agni_ip_windows enable row level security;

-- MARK: - Functions

-- Today's budget row, created on first touch with its ceiling fixed for the day.
--
-- GROWTH IS BOUNDED THREE WAYS: only verified Production paid subscriptions
-- raise it, it may not rise more than max_daily_growth over the previous day,
-- and it never passes hard_max_ceiling_usd. Free installs, trials and abuse
-- cannot move it at all.
create or replace function agni__budget_day(p_day date)
returns agni_budget_days
language plpgsql
security definer
as $$
declare
  b     agni_budget_days%rowtype;
  cfg   agni_budget_config%rowtype;
  paid  integer;
  prev  numeric;
  raw   numeric;
begin
  select * into b from agni_budget_days where day = p_day for update;
  if found then return b; end if;

  select * into cfg from agni_budget_config where id = 1;
  select count(*) into paid from agni_subjects
   where kind = 'subscription' and environment = 'Production' and not is_trial
     and revocation_date is null
     and greatest(expires_date, coalesce(grace_expires_date, expires_date)) > now();
  select ceiling_usd into prev from agni_budget_days where day < p_day order by day desc limit 1;

  raw := cfg.base_ceiling_usd + cfg.per_paid_subscriber_usd * paid;
  insert into agni_budget_days (day, ceiling_usd, paid_subscribers)
  values (p_day,
          least(cfg.hard_max_ceiling_usd, raw,
                greatest(cfg.base_ceiling_usd, coalesce(prev, cfg.base_ceiling_usd) * cfg.max_daily_growth)),
          paid)
  on conflict (day) do nothing;

  select * into b from agni_budget_days where day = p_day for update;
  return b;
end;
$$;

-- Closes one open or expired event. The CALLER holds the period row lock.
--
-- Shared by settle and by the sweep, so a reconciled call and an abandoned one
-- follow the same arithmetic and the same credit rules.
create or replace function agni__finish(
  p_subject text, p_request_id text, p_actual numeric, p_success boolean,
  p_outcome text, p_new_status text,
  p_input integer, p_output integer, p_cache_read integer,
  p_cache_w5 integer, p_cache_w1h integer, p_web integer,
  p_cache_status text, p_http_status integer, p_provider_request_id text
) returns boolean   -- true when a user credit was given back
language plpgsql
security definer
as $$
declare
  e         agni_usage_events%rowtype;
  a         agni_actions%rowtype;
  committed numeric;
  delta     numeric;
  heir      text;
  released  boolean := false;
begin
  select * into e from agni_usage_events
   where subject_id = p_subject and request_id = p_request_id for update;
  if not found or e.status = 'settled' then return false; end if;

  committed := case when e.status = 'expired' then e.actual_usd else e.reserved_usd end;
  delta := greatest(0, coalesce(p_actual, 0)) - committed;

  update agni_usage_events
     set status = p_new_status,
         actual_usd = greatest(0, coalesce(p_actual, 0)),
         outcome = p_outcome,
         input_tokens = p_input, output_tokens = p_output,
         cache_read_tokens = p_cache_read,
         cache_write_5m_tokens = p_cache_w5, cache_write_1h_tokens = p_cache_w1h,
         web_searches = p_web, cache_status = p_cache_status,
         http_status = p_http_status, provider_request_id = p_provider_request_id,
         settled_at = now()
   where subject_id = p_subject and request_id = p_request_id;

  update agni_allowance_periods
     set cost_usd = greatest(0, cost_usd + delta),
         open_reservations = greatest(0, open_reservations - (case when e.status = 'reserved' then 1 else 0 end)),
         updated_at = now()
   where subject_id = p_subject and period_start = e.period_start;

  insert into agni_subject_days (subject_id, day) values (p_subject, e.day) on conflict do nothing;
  update agni_subject_days set cost_usd = greatest(0, cost_usd + delta)
   where subject_id = p_subject and day = e.day;

  perform agni__budget_day(e.day);
  update agni_budget_days
     set free_usd   = free_usd   + case when e.tier = 'free'   then delta else 0 end,
         trial_usd  = trial_usd  + case when e.tier = 'trial'  then delta else 0 end,
         paid_usd   = paid_usd   + case when e.tier = 'pro'    then delta else 0 end,
         beta_usd   = beta_usd   + case when e.tier = 'beta'   then delta else 0 end,
         legacy_usd = legacy_usd + case when e.tier = 'legacy' then delta else 0 end,
         sandbox_usd = sandbox_usd + case when e.tier = 'sandbox' then delta else 0 end,
         companion_usd = companion_usd + case when e.tier = 'companion' then delta else 0 end
   where day = e.day;

  -- THE CREDIT IS DECIDED ONCE, when the call first closes. A late settle of an
  -- expired call corrects the money and leaves the allowance alone.
  if e.status <> 'reserved' or e.action_id is null then return false; end if;

  if p_success then
    -- Only a call that COUNTS can make an action a success. A drink check that
    -- worked must not keep the credit for an estimate that then failed.
    if e.counts then
      update agni_actions set succeeded = true
       where subject_id = p_subject and action_id = e.action_id and bucket = e.bucket;
    end if;
    return false;
  end if;

  if not e.credited then return false; end if;

  select * into a from agni_actions
   where subject_id = p_subject and action_id = e.action_id and bucket = e.bucket for update;
  if a.succeeded then return false; end if;

  -- Another call of the same action is still running and may yet succeed: it
  -- inherits the credit rather than the person being charged twice or not at all.
  select request_id into heir from agni_usage_events
   where subject_id = p_subject and action_id = e.action_id and bucket = e.bucket
     and status = 'reserved' and counts and request_id <> p_request_id
   order by created_at limit 1;
  if heir is not null then
    update agni_usage_events set credited = true where subject_id = p_subject and request_id = heir;
    update agni_usage_events set credited = false where subject_id = p_subject and request_id = p_request_id;
    return false;
  end if;

  -- A FAILED ANALYSIS COSTS NO CREDIT. The provider spend above stays recorded.
  update agni_allowance_periods
     set photo_used  = greatest(0, photo_used  - case when e.bucket = 'photo'  then 1 else 0 end),
         search_used = greatest(0, search_used - case when e.bucket = 'search' then 1 else 0 end),
         web_used    = greatest(0, web_used    - case when e.bucket = 'web'    then 1 else 0 end)
   where subject_id = p_subject and period_start = a.period_start;
  if e.bucket = 'photo' then
    update agni_subject_days set photo_count = greatest(0, photo_count - 1)
     where subject_id = p_subject and day = e.day;
  end if;
  update agni_actions set credited = false
   where subject_id = p_subject and action_id = e.action_id and bucket = e.bucket;
  update agni_usage_events set credited = false where subject_id = p_subject and request_id = p_request_id;
  released := true;
  return released;
end;
$$;

-- Where a new PAID period's usage comes from, if anywhere.
--
-- SWITCHING NEVER BUYS A FRESH ALLOWANCE. A paid period that begins less than
-- a month (less a day, for month-end clamping and early renewal charges) after
-- the previous paid period began is not a new month: a refund and repurchase,
-- an immediate upgrade if the group's levels are ever changed, or Sandbox's
-- accelerated renewals. It carries that period's usage and cost forward.
-- Ordinary renewals, crossgrades at renewal and annual sub-periods all begin a
-- full month after the last, so they start fresh. Trial periods are neither a
-- source nor a destination: trial to paid always starts fresh.
create or replace function agni__carry_source(p_subject text, p_start timestamptz, p_tier text)
returns setof agni_allowance_periods
language sql
stable
security definer
as $$
  select * from agni_allowance_periods q
   where p_tier = 'pro' and q.subject_id = p_subject and q.tier = 'pro'
     and q.period_start < p_start
     and p_start < q.period_start + interval '1 month' - interval '1 day'
   order by q.period_start desc
   limit 1;
$$;

-- RESERVE: the one gate in front of every paid provider call.
--
-- Everything is decided inside one transaction holding the period row, the
-- subject's day row and the day's budget row, in that order (settle takes them
-- in the same order, so the two cannot deadlock). Limits are passed in by the
-- server, which reads them from configuration: changing an allowance is an
-- environment variable, not a migration.
--
-- p_tier is what the caller is ENTITLED to (its allowance period's tier);
-- p_budget_tier is what the call is ACCOUNTED as (ledger, day budget,
-- degradation order). They differ only for Sandbox: entitled 'pro', accounted
-- 'sandbox'.
drop function if exists agni_reserve(text, text, text, text, text, text, boolean, text, text, text,
  timestamptz, timestamptz, integer, numeric, numeric, integer, integer, numeric, integer, integer);
-- The 22-argument version, before p_device_subject (2026-10-31). Dropped so
-- the call below cannot be ambiguous between the two.
drop function if exists agni_reserve(text, text, text, text, text, text, boolean, text, text, text,
  timestamptz, timestamptz, integer, numeric, numeric, integer, integer, numeric, integer, integer, text, integer);
create or replace function agni_reserve(
  p_subject              text,
  p_subject_kind         text,
  p_request_id           text,
  p_action_id            text,
  p_feature              text,
  p_bucket               text,      -- photo | search | web
  p_counts               boolean,   -- does this call consume a credit
  p_tier                 text,      -- free | trial | pro | beta | legacy
  p_auth_path            text,
  p_model                text,
  p_period_start         timestamptz,
  p_period_end           timestamptz,
  p_limit                integer,   -- credits in this bucket this period; null = uncounted
  p_cost_cap             numeric,   -- committed cost allowed this period; null = none
  p_day_cost_cap         numeric,   -- committed cost allowed today; null = none
  p_burst                integer,   -- photo credits allowed today; null = none
  p_uncredited_day_cap   integer,   -- calls using no credit allowed today; null = none
  p_reserve_usd          numeric,
  p_max_calls_per_action integer,
  p_stale_seconds        integer,
  p_budget_tier          text default null,
  p_max_open             integer default null,  -- calls in flight per subject; null = none
  -- WHICH DEVICE MADE THE CALL. Pro usage is pooled on the subscription
  -- subject across every device on it; this lets one device delete only its
  -- own history (schema-deletion.sql). Null for legacy callers and for every
  -- row written before 2026-10-31, and never inferred afterwards.
  p_device_subject       text default null
) returns table (allowed boolean, reason text, credited boolean, used integer,
                 lim integer, period_cost numeric, retry_after integer, alert text)
language plpgsql
security definer
as $$
declare
  now_ts       timestamptz := now();
  today        date := (now() at time zone 'utc')::date;
  next_midnight integer := greatest(1, extract(epoch from
                     (((now() at time zone 'utc')::date + 1)::timestamp at time zone 'utc') - now())::integer);
  until_end    integer;
  p            agni_allowance_periods%rowtype;
  d            agni_subject_days%rowtype;
  a            agni_actions%rowtype;
  have_action  boolean := false;
  b            agni_budget_days%rowtype;
  cfg          agni_budget_config%rowtype;
  need_credit  boolean;
  used_now     integer;
  total        numeric;
  share        numeric;
  level        integer;
  alert_text   text := null;
  stale        record;
  bt           text := coalesce(p_budget_tier, p_tier);
begin
  until_end := case when p_period_end = 'infinity'::timestamptz then 0
                    else greatest(1, extract(epoch from (p_period_end - now_ts))::integer) end;

  insert into agni_subjects (subject_id, kind) values (p_subject, p_subject_kind)
  on conflict (subject_id) do nothing;
  insert into agni_allowance_periods (subject_id, period_start, period_end, tier,
                                      photo_used, search_used, web_used, cost_usd, carried_from)
  select p_subject, p_period_start, p_period_end, p_tier,
         coalesce(c.photo_used, 0), coalesce(c.search_used, 0), coalesce(c.web_used, 0),
         coalesce(c.cost_usd, 0), c.period_start
    from (select 1) one
    left join agni__carry_source(p_subject, p_period_start, p_tier) c on true
  on conflict (subject_id, period_start) do nothing;

  select * into p from agni_allowance_periods
   where subject_id = p_subject and period_start = p_period_start for update;

  -- Abandoned calls in this period close at their reservation: the provider
  -- may have billed, so the money stays committed, and the credit comes back
  -- because nobody received an answer.
  for stale in
    select request_id from agni_usage_events
     where subject_id = p_subject and period_start = p_period_start and status = 'reserved'
       and created_at < now_ts - make_interval(secs => p_stale_seconds)
  loop
    perform agni__finish(p_subject, stale.request_id,
      (select reserved_usd from agni_usage_events where subject_id = p_subject and request_id = stale.request_id),
      false, 'ambiguous_expired', 'expired',
      null, null, null, null, null, null, null, null, null);
  end loop;
  select * into p from agni_allowance_periods
   where subject_id = p_subject and period_start = p_period_start;

  -- THE SAME REQUEST TWICE never reaches the provider twice.
  if exists (select 1 from agni_usage_events where subject_id = p_subject and request_id = p_request_id) then
    return query select false,
      (select case when status = 'reserved' then 'in_flight' else 'duplicate' end
         from agni_usage_events where subject_id = p_subject and request_id = p_request_id),
      false, 0, p_limit, p.cost_usd, 5, null::text;
    return;
  end if;

  if p_action_id is not null then
    select * into a from agni_actions
     where subject_id = p_subject and action_id = p_action_id and bucket = p_bucket for update;
    have_action := found;
  end if;

  -- BOUNDED RETRIES. One tap can make a few calls and a few retries, not an
  -- unbounded stream on one credit.
  if have_action and a.calls >= p_max_calls_per_action then
    return query select false, 'action_limit'::text, false, 0, p_limit, p.cost_usd, 0, null::text;
    return;
  end if;

  -- BOUNDED CONCURRENCY. Each open call holds a reservation that the real cost
  -- should not beat; capping how many are open caps how far a misestimate
  -- (a web search's result size is an estimate, not a bound) can carry a
  -- period past its ceiling.
  if p_max_open is not null and p.open_reservations >= p_max_open then
    return query select false, 'busy'::text, false, 0, p_limit, p.cost_usd, 2, null::text;
    return;
  end if;

  need_credit := p_counts and not (have_action and a.credited);
  used_now := case p_bucket when 'photo' then p.photo_used
                            when 'search' then p.search_used
                            when 'web' then p.web_used else 0 end;

  -- An exhausted allowance refuses new credits, and also refuses the free
  -- helper calls in front of them (a drink check before a photo nobody can
  -- analyse would be money spent on a dead end).
  if p_limit is not null and used_now >= p_limit
     and (need_credit or not (have_action and a.credited)) then
    return query select false, 'allowance'::text, false, used_now, p_limit, p.cost_usd, until_end, null::text;
    return;
  end if;

  insert into agni_subject_days (subject_id, day) values (p_subject, today) on conflict do nothing;
  select * into d from agni_subject_days where subject_id = p_subject and day = today for update;

  if need_credit and p_bucket = 'photo' and p_burst is not null and d.photo_count >= p_burst then
    return query select false, 'burst'::text, false, used_now, p_limit, p.cost_usd, next_midnight, null::text;
    return;
  end if;
  if not need_credit and p_uncredited_day_cap is not null and d.uncredited_count >= p_uncredited_day_cap then
    return query select false, 'burst'::text, false, used_now, p_limit, p.cost_usd, next_midnight, null::text;
    return;
  end if;
  if p_cost_cap is not null and p.cost_usd + p_reserve_usd > p_cost_cap then
    return query select false, 'budget'::text, false, used_now, p_limit, p.cost_usd, until_end, null::text;
    return;
  end if;
  if p_day_cost_cap is not null and d.cost_usd + p_reserve_usd > p_day_cost_cap then
    return query select false, 'spend'::text, false, used_now, p_limit, p.cost_usd, next_midnight, null::text;
    return;
  end if;

  b := agni__budget_day(today);
  select * into cfg from agni_budget_config where id = 1;
  total := b.free_usd + b.trial_usd + b.paid_usd + b.beta_usd + b.legacy_usd + b.sandbox_usd + b.companion_usd;
  share := case bt when 'free' then cfg.free_share
                   when 'legacy' then cfg.free_share
                   when 'trial' then cfg.trial_share
                   when 'sandbox' then cfg.trial_share
                   when 'companion' then cfg.free_share
                   -- Expressed as a share so pro's limit is hard_max_ceiling_usd.
                   when 'pro' then greatest(1, cfg.hard_max_ceiling_usd / greatest(b.ceiling_usd, 0.000001))
                   else 1 end;

  -- PAYING USERS ARE NOT ROUTINE CASUALTIES OF THE DAILY CEILING. Free,
  -- legacy, trial, Sandbox and the companion stop at their share of the
  -- dynamic ceiling, so they can never use more than trial_share of it. A
  -- Production subscriber ('pro') stops only at hard_max_ceiling_usd: their
  -- own spend is already bounded per period (costCapUSD) and per day (burst),
  -- and they are what the ceiling grows from. An operator can still stop
  -- everyone by lowering hard_max_ceiling_usd.
  if total + p_reserve_usd > b.ceiling_usd * share
     or (bt = 'legacy' and b.legacy_usd + p_reserve_usd > cfg.legacy_day_cap_usd)
     or (bt = 'sandbox' and b.sandbox_usd + p_reserve_usd > cfg.sandbox_day_cap_usd)
     or (bt = 'companion' and b.companion_usd + p_reserve_usd > cfg.companion_day_cap_usd) then
    if not (bt = any(b.degraded_tiers)) then
      update agni_budget_days set degraded_tiers = array_append(degraded_tiers, bt) where day = today;
      insert into agni_alerts (kind, detail) values ('degraded',
        jsonb_build_object('day', today, 'tier', bt, 'total_usd', total, 'ceiling_usd', b.ceiling_usd));
      alert_text := 'degraded:' || bt;
    end if;
    return query select false, 'degraded'::text, false, used_now, p_limit, p.cost_usd, next_midnight, alert_text;
    return;
  end if;

  -- ALLOWED. Everything below is one write, under the locks taken above.
  insert into agni_usage_events (subject_id, request_id, action_id, feature, bucket, counts,
                                 tier, auth_path, model, period_start, day, credited, reserved_usd,
                                 device_subject)
  values (p_subject, p_request_id, p_action_id, p_feature, p_bucket, p_counts,
          bt, p_auth_path, p_model, p_period_start, today, need_credit, p_reserve_usd,
          p_device_subject);

  if p_action_id is not null then
    -- The first call's device owns the action row; a later call on the same
    -- action (a part, a retry) does not move it.
    insert into agni_actions (subject_id, action_id, bucket, period_start, calls, credited, device_subject)
    values (p_subject, p_action_id, p_bucket, p_period_start, 1, need_credit, p_device_subject)
    on conflict (subject_id, action_id, bucket) do update
      set calls = agni_actions.calls + 1,
          credited = agni_actions.credited or excluded.credited,
          period_start = case when excluded.credited then excluded.period_start
                              else agni_actions.period_start end;
  end if;

  update agni_allowance_periods
     set photo_used  = photo_used  + case when need_credit and p_bucket = 'photo'  then 1 else 0 end,
         search_used = search_used + case when need_credit and p_bucket = 'search' then 1 else 0 end,
         web_used    = web_used    + case when need_credit and p_bucket = 'web'    then 1 else 0 end,
         cost_usd = cost_usd + p_reserve_usd,
         open_reservations = open_reservations + 1,
         updated_at = now_ts
   where subject_id = p_subject and period_start = p_period_start;

  update agni_subject_days
     set photo_count = photo_count + case when need_credit and p_bucket = 'photo' then 1 else 0 end,
         uncredited_count = uncredited_count + case when need_credit then 0 else 1 end,
         cost_usd = cost_usd + p_reserve_usd
   where subject_id = p_subject and day = today;

  update agni_budget_days
     set free_usd    = free_usd    + case when bt = 'free'    then p_reserve_usd else 0 end,
         trial_usd   = trial_usd   + case when bt = 'trial'   then p_reserve_usd else 0 end,
         paid_usd    = paid_usd    + case when bt = 'pro'     then p_reserve_usd else 0 end,
         beta_usd    = beta_usd    + case when bt = 'beta'    then p_reserve_usd else 0 end,
         legacy_usd  = legacy_usd  + case when bt = 'legacy'  then p_reserve_usd else 0 end,
         sandbox_usd = sandbox_usd + case when bt = 'sandbox' then p_reserve_usd else 0 end,
         companion_usd = companion_usd + case when bt = 'companion' then p_reserve_usd else 0 end
   where day = today;

  total := total + p_reserve_usd;
  level := case when total >= b.ceiling_usd then 100
                when total >= b.ceiling_usd * 0.8 then 80
                when total >= b.ceiling_usd * 0.5 then 50 else 0 end;
  if level > b.alerted_level then
    update agni_budget_days set alerted_level = level where day = today;
    insert into agni_alerts (kind, detail) values ('ceiling',
      jsonb_build_object('day', today, 'level', level, 'total_usd', total, 'ceiling_usd', b.ceiling_usd));
    alert_text := 'ceiling:' || level;
  end if;

  return query select true, 'ok'::text, need_credit,
    used_now + case when need_credit then 1 else 0 end,
    p_limit, p.cost_usd + p_reserve_usd, 0, alert_text;
end;
$$;

-- SETTLE: replaces a reservation with what the provider says the call cost.
-- Idempotent: settling twice changes nothing the second time.
create or replace function agni_settle(
  p_subject text, p_request_id text, p_actual_usd numeric, p_success boolean,
  p_outcome text,
  p_input integer default null, p_output integer default null,
  p_cache_read integer default null, p_cache_w5 integer default null,
  p_cache_w1h integer default null, p_web integer default null,
  p_cache_status text default null, p_http_status integer default null,
  p_provider_request_id text default null
) returns table (settled boolean, credit_released boolean)
language plpgsql
security definer
as $$
declare
  ps        timestamptz;
  st        text;
  released  boolean;
begin
  select period_start, status into ps, st from agni_usage_events
   where subject_id = p_subject and request_id = p_request_id;
  if ps is null or st = 'settled' then
    return query select false, false;
    return;
  end if;
  perform 1 from agni_allowance_periods
   where subject_id = p_subject and period_start = ps for update;
  released := agni__finish(p_subject, p_request_id, p_actual_usd, p_success, p_outcome, 'settled',
                           p_input, p_output, p_cache_read, p_cache_w5, p_cache_w1h, p_web,
                           p_cache_status, p_http_status, p_provider_request_id);
  return query select true, released;
end;
$$;

-- Closes every abandoned reservation, everywhere. For a scheduled job or the
-- operator; reserve already sweeps the caller's own period on every call.
create or replace function agni_sweep_reservations(p_stale_seconds integer default 120)
returns integer
language plpgsql
security definer
as $$
declare
  r      record;
  closed integer := 0;
begin
  for r in
    select subject_id, request_id, period_start, reserved_usd from agni_usage_events
     where status = 'reserved' and created_at < now() - make_interval(secs => p_stale_seconds)
     order by subject_id, period_start
  loop
    perform 1 from agni_allowance_periods
     where subject_id = r.subject_id and period_start = r.period_start for update;
    perform agni__finish(r.subject_id, r.request_id, r.reserved_usd, false, 'ambiguous_expired',
                         'expired', null, null, null, null, null, null, null, null, null);
    closed := closed + 1;
  end loop;
  return closed;
end;
$$;

-- What the app shows: credits used per bucket this period and photos today.
-- A period not started yet shows what it WILL carry (agni__carry_source), so
-- the app never shows a fresh allowance that the first call would not honour.
drop function if exists agni_allowance_status(text, timestamptz);
create or replace function agni_allowance_status(p_subject text, p_period_start timestamptz,
                                                 p_tier text default null)
returns table (photo_used integer, search_used integer, web_used integer,
               cost_usd numeric, photos_today integer,
               free_photo_exhausted boolean, free_search_exhausted boolean)
language sql
security definer
as $$
  select coalesce(p.photo_used, c.photo_used, 0), coalesce(p.search_used, c.search_used, 0),
         coalesce(p.web_used, c.web_used, 0), coalesce(p.cost_usd, c.cost_usd, 0),
         coalesce((select photo_count from agni_subject_days
                    where subject_id = p_subject and day = (now() at time zone 'utc')::date), 0),
         coalesce((select s.free_photo_exhausted from agni_subjects s where s.subject_id = p_subject), false),
         coalesce((select s.free_search_exhausted from agni_subjects s where s.subject_id = p_subject), false)
    from (select 1) one
    left join agni_allowance_periods p
      on p.subject_id = p_subject and p.period_start = p_period_start
    left join agni__carry_source(p_subject, p_period_start, p_tier) c on p.subject_id is null;
$$;

-- Writes a verified subscription transaction.
--
-- NEVER GOES BACKWARDS. A newer purchase replaces an older one; the same
-- purchase re-signed later (a refund, a revocation) updates it; an OLDER
-- purchase, however recently signed, changes nothing. Without that, a client
-- re-sending last month's transaction could roll back an expiry date, and an
-- App Store notification arriving out of order could undo a refund.
create or replace function agni_subscription_upsert(
  p_original_transaction_id text, p_transaction_id text, p_product_id text,
  p_environment text, p_purchase_date timestamptz, p_original_purchase_date timestamptz,
  p_expires_date timestamptz, p_revocation_date timestamptz, p_revocation_reason integer,
  p_offer_type integer, p_offer_discount_type text, p_is_trial boolean,
  p_grace_expires_date timestamptz, p_auto_renew boolean, p_signed_date timestamptz
) returns table (subject_id text, purchase_date timestamptz, expires_date timestamptz,
                 revocation_date timestamptz, is_trial boolean, product_id text,
                 environment text, grace_expires_date timestamptz, applied boolean)
language plpgsql
security definer
as $$
declare
  -- Production and Sandbox never share a subject.
  sid      text := case when p_environment = 'Production' then 'sub:' else 'sbx:' end
                   || p_original_transaction_id;
  cur      agni_subjects%rowtype;
  apply    boolean;
begin
  insert into agni_subjects (subject_id, kind, original_transaction_id)
  values (sid, 'subscription', p_original_transaction_id)
  on conflict on constraint agni_subjects_pkey do nothing;

  select * into cur from agni_subjects s where s.subject_id = sid for update;
  apply := cur.purchase_date is null
        or p_purchase_date > cur.purchase_date
        or (p_purchase_date = cur.purchase_date
            and (cur.signed_date is null or p_signed_date >= cur.signed_date));

  if apply then
    update agni_subjects s
       set environment = p_environment, product_id = p_product_id,
           transaction_id = p_transaction_id, purchase_date = p_purchase_date,
           original_purchase_date = p_original_purchase_date,
           expires_date = p_expires_date, revocation_date = p_revocation_date,
           revocation_reason = p_revocation_reason, offer_type = p_offer_type,
           offer_discount_type = p_offer_discount_type, is_trial = p_is_trial,
           grace_expires_date = coalesce(p_grace_expires_date, s.grace_expires_date),
           auto_renew = coalesce(p_auto_renew, s.auto_renew),
           signed_date = p_signed_date, updated_at = now()
     where s.subject_id = sid;
  elsif p_grace_expires_date is not null or p_auto_renew is not null then
    -- Renewal information is about the subscription, not one transaction, so
    -- it applies even when the transaction it arrived with is older.
    update agni_subjects s
       set grace_expires_date = coalesce(p_grace_expires_date, s.grace_expires_date),
           auto_renew = coalesce(p_auto_renew, s.auto_renew), updated_at = now()
     where s.subject_id = sid;
  end if;

  return query select s.subject_id, s.purchase_date, s.expires_date, s.revocation_date,
                      s.is_trial, s.product_id, s.environment, s.grace_expires_date, apply
                 from agni_subjects s where s.subject_id = sid;
end;
$$;

-- Ties an attested key to its device subject (once, permanently) and, when a
-- verified subscription is presented, to that subscription.
--
-- A SUBSCRIPTION SHARED TOO WIDELY IS REFUSED, not silently allowed: more than
-- p_max_keys installs in 30 days is a leaked transaction, not a family. The
-- allowance is per subscription anyway, so sharing never multiplies the spend;
-- this stops one leaked JWS becoming a public pool.
create or replace function agni_link_key(
  p_key_id text, p_device_subject text, p_subscription_subject text, p_max_keys integer
) returns table (device_subject text, subscription_subject text, linked boolean, reason text)
language plpgsql
security definer
as $$
declare
  l       agni_key_links%rowtype;
  n       integer;
begin
  insert into agni_subjects (subject_id, kind) values (p_device_subject, 'device')
  on conflict (subject_id) do nothing;
  insert into agni_key_links (key_id, device_subject) values (p_key_id, p_device_subject)
  on conflict (key_id) do nothing;
  select * into l from agni_key_links k where k.key_id = p_key_id for update;

  if p_subscription_subject is null then
    return query select l.device_subject, l.subscription_subject, true, 'ok'::text;
    return;
  end if;

  if l.subscription_subject is distinct from p_subscription_subject then
    select count(*) into n from agni_key_links k
     where k.subscription_subject = p_subscription_subject
       and k.subscription_linked_at > now() - interval '30 days';
    if n >= p_max_keys then
      update agni_subjects set flagged = 'too_many_installs', updated_at = now()
       where agni_subjects.subject_id = p_subscription_subject;
      insert into agni_alerts (kind, detail) values ('subscription_shared',
        jsonb_build_object('subject', p_subscription_subject, 'installs', n));
      return query select l.device_subject, l.subscription_subject, false, 'too_many_installs'::text;
      return;
    end if;
    update agni_key_links k
       set subscription_subject = p_subscription_subject, subscription_linked_at = now()
     where k.key_id = p_key_id;
  end if;

  return query select l.device_subject, p_subscription_subject, true, 'ok'::text;
end;
$$;

-- Everything the server needs to decide a key's tier, in one read.
create or replace function agni_key_context(p_key_id text)
returns table (device_subject text, free_photo_exhausted boolean, free_search_exhausted boolean,
               devicecheck_checked_at timestamptz,
               subscription_subject text, product_id text, environment text,
               purchase_date timestamptz, original_purchase_date timestamptz,
               expires_date timestamptz, revocation_date timestamptz,
               is_trial boolean, grace_expires_date timestamptz)
language sql
security definer
as $$
  select l.device_subject, coalesce(d.free_photo_exhausted, false),
         coalesce(d.free_search_exhausted, false), d.devicecheck_checked_at,
         l.subscription_subject, s.product_id, s.environment,
         s.purchase_date, s.original_purchase_date, s.expires_date, s.revocation_date,
         coalesce(s.is_trial, false), s.grace_expires_date
    from agni_key_links l
    left join agni_subjects d on d.subject_id = l.device_subject
    left join agni_subjects s on s.subject_id = l.subscription_subject
   where l.key_id = p_key_id;
$$;

-- DeviceCheck said this device has used its Free sample already (or we just
-- told DeviceCheck so). An abuse signal, not a ledger: it only ever closes the
-- sample, never reopens it.
create or replace function agni_mark_device(p_subject text, p_photo boolean, p_search boolean)
returns void
language sql
security definer
as $$
  update agni_subjects
     set free_photo_exhausted = free_photo_exhausted or p_photo,
         free_search_exhausted = free_search_exhausted or p_search,
         devicecheck_checked_at = now(), updated_at = now()
   where subject_id = p_subject;
$$;

-- Whether a notification was already applied. Checked BEFORE the write;
-- agni_store_notification_seen records it only AFTER the write succeeded.
create or replace function agni_store_notification_known(p_uuid text)
returns boolean
language sql
stable
security definer
as $$
  select exists (select 1 from agni_store_notifications where notification_uuid = p_uuid);
$$;

-- One App Store notification, once. Returns false for a redelivery.
create or replace function agni_store_notification_seen(
  p_uuid text, p_type text, p_subtype text, p_original_transaction_id text, p_signed_date timestamptz
) returns boolean
language plpgsql
security definer
as $$
declare
  n integer;
begin
  insert into agni_store_notifications (notification_uuid, notification_type, subtype,
                                        original_transaction_id, signed_date)
  values (p_uuid, p_type, p_subtype, p_original_transaction_id, p_signed_date)
  on conflict (notification_uuid) do nothing;
  get diagnostics n = row_count;
  return n = 1;
end;
$$;

-- A fixed window per IP hash. True when the request is inside the limit.
create or replace function agni_ip_window(
  p_bucket text, p_ip_hash text, p_window_seconds integer, p_limit integer
) returns boolean
language plpgsql
security definer
as $$
declare
  c integer;
begin
  insert into agni_ip_windows as w (bucket, ip_hash, window_start, count)
  values (p_bucket, p_ip_hash, now(), 1)
  on conflict (bucket, ip_hash) do update
    set count = case when w.window_start < now() - make_interval(secs => p_window_seconds)
                     then 1 else w.count + 1 end,
        window_start = case when w.window_start < now() - make_interval(secs => p_window_seconds)
                            then now() else w.window_start end
  returning count into c;
  -- Housekeeping, occasionally.
  if random() < 0.01 then
    delete from agni_ip_windows where window_start < now() - interval '1 day';
  end if;
  return c <= p_limit;
end;
$$;

-- MARK: - Operator views

-- Spend per day, tier, feature and model, from the ledger. The number to
-- reconcile against the Anthropic Console's usage page.
-- security_invoker, and no grant to anon or authenticated: a plain view runs
-- as its owner and would read past the ledger's row level security.
create or replace view agni_usage_daily with (security_invoker = true) as
  select day, tier, feature, model,
         count(*)                                   as calls,
         count(*) filter (where outcome = 'ok')     as ok,
         count(*) filter (where status = 'reserved') as open,
         sum(coalesce(actual_usd, reserved_usd))    as cost_usd,
         sum(input_tokens)                          as input_tokens,
         sum(output_tokens)                         as output_tokens,
         sum(cache_read_tokens)                     as cache_read_tokens,
         sum(coalesce(cache_write_5m_tokens, 0) + coalesce(cache_write_1h_tokens, 0)) as cache_write_tokens,
         sum(web_searches)                          as web_searches,
         count(*) filter (where cache_status = 'hit') as prompt_cache_hits
    from agni_usage_events
   group by day, tier, feature, model;

-- MARK: - Shared research cache

-- What a model said a FOOD is, keyed by the normalised words and nothing else.
-- Same rules as agni_ingredient_evidence: no column for a person, no meal, no
-- install. A hit costs nothing and uses no credit.
create table if not exists agni_research_cache (
  key         text primary key,
  payload     jsonb not null,
  hits        integer not null default 0,
  created_at  timestamptz not null default now(),
  expires_at  timestamptz not null
);
alter table agni_research_cache enable row level security;

create or replace function agni_research_cache_get(p_key text)
returns jsonb
language plpgsql
security definer
as $$
declare
  found_payload jsonb;
begin
  update agni_research_cache set hits = hits + 1
   where key = p_key and expires_at > now()
   returning payload into found_payload;
  return found_payload;
end;
$$;

create or replace function agni_research_cache_put(p_key text, p_payload jsonb, p_ttl_seconds integer)
returns void
language sql
security definer
as $$
  insert into agni_research_cache (key, payload, expires_at)
  values (p_key, p_payload, now() + make_interval(secs => p_ttl_seconds))
  on conflict (key) do update
    set payload = excluded.payload, expires_at = excluded.expires_at, created_at = now();
$$;

-- MARK: - One read per request

-- Links a key to its device subject if it is not linked yet (never re-links),
-- and returns everything needed to decide its tier. One round trip.
create or replace function agni_caller(p_key_id text, p_device_subject text)
returns table (device_subject text, free_photo_exhausted boolean, free_search_exhausted boolean,
               devicecheck_checked_at timestamptz,
               subscription_subject text, product_id text, environment text,
               purchase_date timestamptz, original_purchase_date timestamptz,
               expires_date timestamptz, revocation_date timestamptz,
               is_trial boolean, grace_expires_date timestamptz)
language plpgsql
security definer
as $$
begin
  if not exists (select 1 from agni_key_links k where k.key_id = p_key_id) then
    insert into agni_subjects (subject_id, kind) values (p_device_subject, 'device')
    on conflict (subject_id) do nothing;
    insert into agni_key_links (key_id, device_subject) values (p_key_id, p_device_subject)
    on conflict (key_id) do nothing;
  end if;
  return query select * from agni_key_context(p_key_id);
end;
$$;

-- MARK: - Who may call these

-- ONLY THE SERVER. Postgres grants EXECUTE on new functions to PUBLIC, and
-- Supabase exposes public functions over its REST API to the anon and
-- authenticated roles. The anon key is not in the app, but a ledger that
-- moves money must not depend on that: every billing function here is
-- callable by service_role alone.
do $$
declare
  f record;
begin
  for f in
    select p.oid::regprocedure as sig
      from pg_proc p join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public'
       and p.proname in ('agni__budget_day', 'agni__finish', 'agni__carry_source', 'agni_reserve',
                         'agni_settle', 'agni_sweep_reservations', 'agni_allowance_status',
                         'agni_subscription_upsert', 'agni_link_key', 'agni_key_context',
                         'agni_mark_device', 'agni_store_notification_known',
                         'agni_store_notification_seen', 'agni_ip_window',
                         'agni_research_cache_get', 'agni_research_cache_put', 'agni_caller')
  loop
    execute format('revoke execute on function %s from public', f.sig);
    if exists (select 1 from pg_roles where rolname = 'anon') then
      execute format('revoke execute on function %s from anon', f.sig);
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
      execute format('revoke execute on function %s from authenticated', f.sig);
    end if;
    if exists (select 1 from pg_roles where rolname = 'service_role') then
      execute format('grant execute on function %s to service_role', f.sig);
    end if;
  end loop;
end;
$$;

do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on agni_usage_daily from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on agni_usage_daily from authenticated';
  end if;
end;
$$;


-- ===== schema-community.sql =====
-- The shared dish table. Run this once in the Agni Supabase SQL editor,
-- after schema.sql.
--
-- Every dish somebody adds by hand is contributed silently. Nobody is asked,
-- because a prompt is a tax on the person doing the app a favour and most
-- people would decline it out of habit rather than intent.
--
-- Silence puts the burden on this file instead. Two rules do the work.
--
-- ONE ROW PER DISH PER INSTALL, so the same person entering chapati fifty times
-- is one voice, not fifty. Re-entering it updates their figures rather than
-- stacking another vote.
--
-- AND NOTHING IS PUBLISHED UNTIL TWO INDEPENDENT INSTALLS HAVE NAMED IT. That
-- single rule does two jobs at once. It is the privacy gate: "Amma's
-- kozhukatta" or "leftover from Priya's party" is typed by exactly one person
-- and is therefore never shown to anybody. And it is the quality gate: a name
-- two strangers both arrived at is a real dish, and the figures can be taken as
-- the median of what they each said rather than on the word of whoever typed
-- first.

create table if not exists agni_dish_submissions (
  -- The normalised name, matching DishDatabase.normalise on the app side:
  -- lowercased, punctuation stripped, whitespace collapsed. Two people writing
  -- "Kothu Parotta" and "kothu  parotta" are agreeing, and this is what makes
  -- them agree.
  key             text        not null,
  -- As typed, for display. The most common spelling wins when published.
  name            text        not null,
  -- NOT the raw install id since 2026-10-31: a keyed hash of it (`c1:...`,
  -- contributorId in api/_lib.js). Tells one phone from another for the rules
  -- below. Pseudonymous: the server can recompute it from an install id, so it
  -- is not a plain-equality join to usage records, but it is not anonymous.
  install_id      text        not null,

  unit            text        not null default 'serving',
  grams_per_unit  numeric     not null default 0,
  kcal            numeric     not null,
  protein_g       numeric     not null default 0,
  carbs_g         numeric     not null default 0,
  fat_g           numeric     not null default 0,

  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),

  primary key (key, install_id)
);

create index if not exists agni_dish_submissions_key_idx on agni_dish_submissions (key);

-- Locked down like the installs table. Only the service role key held by the
-- Vercel function touches this; no browser and no app ever reaches it directly.
alter table agni_dish_submissions enable row level security;

-- What has earned its way out. Two independent installs minimum, and the
-- figures are the MEDIAN of what each of them said, not a mean: one person
-- typing 2000 kcal for a chapati should not drag the answer, and with three
-- submissions the median simply ignores them.
create or replace view agni_community_dishes as
  select
    s.key,
    mode() within group (order by s.name)                                  as name,
    mode() within group (order by s.unit)                                  as unit,
    percentile_cont(0.5) within group (order by s.grams_per_unit)          as grams_per_unit,
    percentile_cont(0.5) within group (order by s.kcal)                    as kcal,
    percentile_cont(0.5) within group (order by s.protein_g)               as protein_g,
    percentile_cont(0.5) within group (order by s.carbs_g)                 as carbs_g,
    percentile_cont(0.5) within group (order by s.fat_g)                   as fat_g,
    count(*)::int                                                          as submitters,
    max(s.updated_at)                                                      as last_seen
  from agni_dish_submissions s
  group by s.key
  having count(*) >= 2;

-- Records one person's version of a dish, replacing their own previous answer.
--
-- Figures are checked here rather than only in the app, because the app is not
-- the only thing that can call this. Anything impossible is dropped silently:
-- the person who typed it is not doing anything wrong, they are just not going
-- to be told their chapati was rejected, and there is nothing useful to say.
create or replace function agni_submit_dish(
  p_install_id     text,
  p_key            text,
  p_name           text,
  p_unit           text,
  p_grams_per_unit numeric,
  p_kcal           numeric,
  p_protein_g      numeric,
  p_carbs_g        numeric,
  p_fat_g          numeric
) returns void
language plpgsql
security definer
as $$
begin
  -- A name is a dish, not a sentence. Anything past this is a note somebody
  -- wrote to themselves, and it would be published to strangers.
  if p_key is null or length(p_key) < 3 or length(p_key) > 60 then return; end if;
  if p_install_id is null or length(p_install_id) < 8 then return; end if;

  -- Nothing edible is denser than pure fat, and no single serving of anything
  -- is 5,000 kcal. Both ends are typing errors rather than food.
  if p_kcal is null or p_kcal <= 0 or p_kcal > 5000 then return; end if;
  if p_protein_g < 0 or p_carbs_g < 0 or p_fat_g < 0 then return; end if;
  if p_grams_per_unit < 0 or p_grams_per_unit > 5000 then return; end if;

  -- The macros have to be able to produce the calories. Four, four and nine,
  -- with a wide allowance for fibre, alcohol and rounding: this only catches
  -- somebody who typed the protein into the calorie box.
  if (p_protein_g * 4 + p_carbs_g * 4 + p_fat_g * 9) > p_kcal * 3 then return; end if;

  insert into agni_dish_submissions as d
    (key, name, install_id, unit, grams_per_unit, kcal, protein_g, carbs_g, fat_g)
  values
    (p_key, p_name, p_install_id, coalesce(nullif(p_unit, ''), 'serving'),
     p_grams_per_unit, p_kcal, p_protein_g, p_carbs_g, p_fat_g)
  on conflict (key, install_id) do update set
    name = excluded.name,
    unit = excluded.unit,
    grams_per_unit = excluded.grams_per_unit,
    kcal = excluded.kcal,
    protein_g = excluded.protein_g,
    carbs_g = excluded.carbs_g,
    fat_g = excluded.fat_g,
    updated_at = now();
end;
$$;

-- Search, over published dishes only. The view is what enforces that, so no
-- endpoint can leak an uncorroborated entry by forgetting a condition.
create or replace function agni_search_dishes(p_query text, p_limit int default 15)
returns table (
  key text, name text, unit text, grams_per_unit numeric,
  kcal numeric, protein_g numeric, carbs_g numeric, fat_g numeric, submitters int
)
language sql
stable
security definer
as $$
  select c.key, c.name, c.unit, c.grams_per_unit,
         c.kcal, c.protein_g, c.carbs_g, c.fat_g, c.submitters
  from agni_community_dishes c
  where length(coalesce(p_query, '')) >= 2
    and c.key like '%' || lower(trim(p_query)) || '%'
  -- Names that START with what was typed first, then the best corroborated.
  order by (c.key like lower(trim(p_query)) || '%') desc, c.submitters desc, c.key
  limit least(coalesce(p_limit, 15), 50);
$$;

-- What to add to the bundled table next, best corroborated first. This is the
-- whole point of collecting it: the list is evidence rather than a guess.
--   select * from agni_community_dishes order by submitters desc limit 50;


-- ===== schema-misses.sql =====
-- What Agni did not know. Run once in the Agni Supabase project.
--
-- Every phone is already keeping this list locally: the dishes a photo could
-- not match, the searches that came back empty, the barcodes with nothing
-- behind them, and the strongest signal of all, a dish somebody looked at their
-- own plate and NAMED that the table had no entry for. None of it reaches
-- anyone, so the one question worth answering, "what should be added next",
-- is still being answered by guessing.
--
-- Different from agni_dish_submissions in one important way. That table is
-- republished to strangers, so it needs two independent submitters before
-- anything is shown. This one is read only by Shine, deciding what to build,
-- and its whole value is the LONG TAIL: a dish one person wanted is exactly the
-- kind of thing a curated table misses. So single reports are kept, and the
-- install count is surfaced instead so the list can be ordered by how many
-- people wanted a thing rather than how loudly one person did.
--
-- It holds dish names and a keyed hash of the install id (`c1:...`, see
-- contributorId in api/_lib.js), never the raw id since 2026-10-31. No account
-- and no email. The hash is pseudonymous: the server can recompute it from an
-- install id, so a row is linkable to a phone by whoever holds the key.

create table if not exists agni_dish_misses (
  key         text        not null,   -- normalised, matching DishDatabase.normalise
  name        text        not null,   -- as typed or as the model said it
  kind        text        not null,   -- photoNotAnchored | searchFoundNothing | barcodeNotFound | namedByYou
  install_id  text        not null,
  times       integer     not null default 1,
  first_seen  timestamptz not null default now(),
  last_seen   timestamptz not null default now(),
  updated_at  timestamptz not null default now(),

  -- One row per dish per kind per phone. The phone sends its running count, so
  -- re-sending the same list is idempotent rather than additive: an upload that
  -- happens twice must not double what it reports.
  primary key (key, kind, install_id)
);

create index if not exists agni_dish_misses_key_idx on agni_dish_misses (key);

alter table agni_dish_misses enable row level security;

-- The backlog, most wanted first.
--
--   select * from agni_missing_dishes limit 50;
create or replace view agni_missing_dishes as
  select
    m.key,
    mode() within group (order by m.name)      as name,
    count(distinct m.install_id)::int          as people,
    sum(m.times)::int                          as times,
    -- Named by a person beats anything a model or a search produced, so it is
    -- worth seeing at a glance which kind of miss this mostly is.
    mode() within group (order by m.kind)      as mostly,
    bool_or(m.kind = 'namedByYou')             as someone_named_it,
    max(m.last_seen)                           as last_seen
  from agni_dish_misses m
  group by m.key;

create or replace function agni_report_miss(
  p_install_id text,
  p_key        text,
  p_name       text,
  p_kind       text,
  p_times      integer,
  p_first_seen timestamptz,
  p_last_seen  timestamptz
) returns void
language plpgsql
security definer
as $$
begin
  -- A name is a dish, not a sentence somebody wrote to themselves.
  if p_key is null or length(p_key) < 3 or length(p_key) > 60 then return; end if;
  if p_install_id is null or length(p_install_id) < 8 then return; end if;
  if p_kind not in ('photoNotAnchored', 'searchFoundNothing',
                    'barcodeNotFound', 'namedByYou') then return; end if;

  insert into agni_dish_misses as d
    (key, name, kind, install_id, times, first_seen, last_seen)
  values
    (p_key, p_name, p_kind, p_install_id,
     greatest(coalesce(p_times, 1), 1),
     coalesce(p_first_seen, now()), coalesce(p_last_seen, now()))
  on conflict (key, kind, install_id) do update set
    name = excluded.name,
    -- The phone's running total REPLACES what is stored rather than adding to
    -- it. Adding would make an upload that ran twice look like twice the
    -- interest, which is the one thing this list must not get wrong.
    times = greatest(excluded.times, d.times),
    last_seen = greatest(excluded.last_seen, d.last_seen),
    updated_at = now();
end;
$$;


-- ===== schema-deletion.sql =====
-- Server-data deletion, asked for by the person in the app.
-- PREPARED 2026-10-31, NOT YET APPLIED TO PRODUCTION. Run after
-- schema-billing.sql (which adds the device_subject columns) and before
-- schema-lockdown.sql. Spec: Agni repo docs/legal-drafts/deletion-design.md.
--
-- WHO MAY DELETE WHAT is decided in Node (api/_deletion.js), never here and
-- never from anything the client names: the device subject comes from the
-- App Attest key that signed the request, and the subscription subject from
-- that key's link plus a verified Apple transaction. These functions trust
-- their arguments, which is why only the service role can call them.
--
-- WHAT IS ALWAYS KEPT, in both scopes:
--   * this period's allowance counters and today's daily counts: deleting
--     them would reset the allowance and the daily photo limit;
--   * this period's action rows: they make a retried photo free;
--   * open reservations: a call still in flight. Both functions refuse to run
--     while one is open (outcome 'blocked'); the app asks again in a minute;
--   * the Free-sample markers on the device subject: otherwise a deletion
--     would hand out a fresh Free sample;
--   * the App Attest key row and the key's links: deleting the key breaks the
--     phone's next request, and the link is what keeps Pro on;
--   * the subscription subject's Apple transaction fields and the App Store
--     notices for it: needed to restore, to apply refunds and revocations,
--     and to catch one purchase shared across too many devices.
--
-- ROWS WITHOUT A DEVICE (device_subject is null: every subscription usage row
-- written before 2026-10-31) are never assumed to be anybody's. The device
-- scope leaves them alone; only the purchaser's subscription scope removes
-- them, because that scope covers every device on the subscription.
--
-- Both functions return one row per category: outcome 'deleted' or 'kept'
-- (or a single 'blocked' row), the row count, and the reason a kept category
-- was kept, which the app shows as written.

create or replace function agni__deletion_open(p_device_subject text, p_subscription_subject text,
                                               p_whole_subscription boolean)
returns integer
language sql
security definer
as $$
  select count(*)::int from agni_usage_events e
   where e.status = 'reserved'
     and (e.subject_id = p_device_subject
          or (p_subscription_subject is not null and e.subject_id = p_subscription_subject
              and (p_whole_subscription or e.device_subject = p_device_subject)));
$$;

create or replace function agni__deletion_alert(p_scope text, p_counts jsonb)
returns void
language sql
security definer
as $$
  -- Counts only. No subject, key or install id: the log of deletions must not
  -- itself be a record of who asked.
  insert into agni_alerts (kind, detail) values ('deletion', jsonb_build_object('scope', p_scope, 'counts', p_counts));
$$;

-- MARK: - Scope A: this phone

create or replace function agni_delete_device_data(
  p_device_subject       text,
  p_contributors         text[],     -- the raw install id and its c1: hash, computed in Node
  p_subscription_subject text default null
) returns table (category text, outcome text, rows bigint, reason text)
language plpgsql
security definer
as $$
declare
  n bigint;
  open_now integer;
  counts jsonb := '{}'::jsonb;
  today date := (now() at time zone 'utc')::date;
begin
  if p_device_subject is null or p_device_subject not like 'dev:%' then
    raise exception 'agni_delete_device_data: not a device subject';
  end if;

  open_now := agni__deletion_open(p_device_subject, p_subscription_subject, false);
  if open_now > 0 then
    category := 'open_reservations'; outcome := 'blocked'; rows := open_now;
    reason := 'A request from this phone is still being processed.'; return next;
    return;
  end if;

  -- Deleted ------------------------------------------------------------------

  delete from agni_usage_events e where e.subject_id = p_device_subject and e.status <> 'reserved';
  get diagnostics n = row_count;
  category := 'usage_events'; outcome := 'deleted'; rows := n; reason := null; return next;
  counts := counts || jsonb_build_object('usage_events', n);

  delete from agni_actions a
   where a.subject_id = p_device_subject
     and a.period_start not in (select p.period_start from agni_allowance_periods p
                                 where p.subject_id = p_device_subject and p.period_end > now());
  get diagnostics n = row_count;
  category := 'past_actions'; outcome := 'deleted'; rows := n; reason := null; return next;
  counts := counts || jsonb_build_object('past_actions', n);

  delete from agni_allowance_periods p where p.subject_id = p_device_subject and p.period_end <= now();
  get diagnostics n = row_count;
  category := 'past_allowance_periods'; outcome := 'deleted'; rows := n; reason := null; return next;
  counts := counts || jsonb_build_object('past_allowance_periods', n);

  delete from agni_subject_days d where d.subject_id = p_device_subject and d.day < today;
  get diagnostics n = row_count;
  category := 'past_daily_counts'; outcome := 'deleted'; rows := n; reason := null; return next;
  counts := counts || jsonb_build_object('past_daily_counts', n);

  if p_subscription_subject is not null then
    delete from agni_usage_events e
     where e.subject_id = p_subscription_subject and e.device_subject = p_device_subject
       and e.status <> 'reserved';
    get diagnostics n = row_count;
    category := 'subscription_usage_events_from_this_phone'; outcome := 'deleted'; rows := n; reason := null; return next;
    counts := counts || jsonb_build_object('subscription_usage_events_from_this_phone', n);

    delete from agni_actions a
     where a.subject_id = p_subscription_subject and a.device_subject = p_device_subject
       and a.period_start not in (select p.period_start from agni_allowance_periods p
                                   where p.subject_id = p_subscription_subject and p.period_end > now());
    get diagnostics n = row_count;
    category := 'subscription_past_actions_from_this_phone'; outcome := 'deleted'; rows := n; reason := null; return next;
    counts := counts || jsonb_build_object('subscription_past_actions_from_this_phone', n);
  end if;

  delete from agni_dish_submissions s where s.install_id = any(p_contributors);
  get diagnostics n = row_count;
  category := 'dish_contributions'; outcome := 'deleted'; rows := n; reason := null; return next;
  counts := counts || jsonb_build_object('dish_contributions', n);

  delete from agni_dish_misses m where m.install_id = any(p_contributors);
  get diagnostics n = row_count;
  category := 'missed_dish_reports'; outcome := 'deleted'; rows := n; reason := null; return next;
  counts := counts || jsonb_build_object('missed_dish_reports', n);

  -- Kept ---------------------------------------------------------------------

  select count(*) into n from agni_allowance_periods p
   where p.period_end > now()
     and (p.subject_id = p_device_subject or p.subject_id = p_subscription_subject);
  category := 'current_allowance_counters'; outcome := 'kept'; rows := n;
  reason := 'Counts for this period only. Deleting them would reset your AI allowance.'; return next;

  select count(*) into n from agni_subject_days d
   where d.day = today and (d.subject_id = p_device_subject or d.subject_id = p_subscription_subject);
  category := 'todays_counts'; outcome := 'kept'; rows := n;
  reason := 'Today''s photo count. Deleting it would reset the daily photo limit.'; return next;

  select count(*) into n from agni_actions a
   where (a.subject_id = p_device_subject
          and a.period_start in (select p.period_start from agni_allowance_periods p
                                  where p.subject_id = p_device_subject and p.period_end > now()))
      or (a.subject_id = p_subscription_subject and a.device_subject = p_device_subject
          and a.period_start in (select p.period_start from agni_allowance_periods p
                                  where p.subject_id = p_subscription_subject and p.period_end > now()));
  category := 'current_period_requests'; outcome := 'kept'; rows := n;
  reason := 'This period''s request ids. They stop a retried photo being charged twice.'; return next;

  select count(*) into n from agni_subjects d
   where d.subject_id = p_device_subject and (d.free_photo_exhausted or d.free_search_exhausted);
  category := 'free_sample_used_marker'; outcome := 'kept'; rows := n;
  reason := 'Records that this phone has used its free AI sample, so deleting cannot hand out another.'; return next;

  select count(*) into n from agni_key_links l where l.device_subject = p_device_subject;
  category := 'device_key'; outcome := 'kept'; rows := n;
  reason := 'This phone''s security key (a public key, nothing personal). Agni needs it to accept requests from this phone.'; return next;

  if p_subscription_subject is not null then
    category := 'subscription_purchase_record'; outcome := 'kept'; rows := 1;
    reason := 'Apple''s purchase record for your subscription. Needed to restore it and to apply refunds. Never your name, email or payment details.'; return next;

    select count(*) into n from agni_usage_events e
     where e.subject_id = p_subscription_subject and e.device_subject is null;
    category := 'subscription_history_unattributed'; outcome := 'kept'; rows := n;
    reason := 'Subscription use from before Agni recorded which device made it. It cannot be shown to be this phone''s, so it is kept until it expires. The person who bought the subscription can delete it.'; return next;

    select count(*) into n from agni_usage_events e
     where e.subject_id = p_subscription_subject and e.device_subject is distinct from p_device_subject
       and e.device_subject is not null;
    category := 'subscription_history_other_devices'; outcome := 'kept'; rows := n;
    reason := 'Use of the same subscription from other devices. This phone can only delete its own.'; return next;
  end if;

  perform agni__deletion_alert('device', counts);
end;
$$;

-- MARK: - Scope B: the purchaser's whole subscription history

create or replace function agni_delete_subscription_history(
  p_subscription_subject text,
  p_device_subject       text,
  p_contributors         text[]
) returns table (category text, outcome text, rows bigint, reason text)
language plpgsql
security definer
as $$
declare
  n bigint;
  open_now integer;
  counts jsonb := '{}'::jsonb;
  today date := (now() at time zone 'utc')::date;
  otid text;
begin
  if p_subscription_subject is null or p_subscription_subject !~ '^(sub|sbx):' then
    raise exception 'agni_delete_subscription_history: not a subscription subject';
  end if;
  open_now := agni__deletion_open(p_device_subject, p_subscription_subject, true);
  if open_now > 0 then
    category := 'open_reservations'; outcome := 'blocked'; rows := open_now;
    reason := 'A request on this subscription is still being processed.'; return next;
    return;
  end if;

  -- Everything this phone could delete on its own first, so the counts
  -- include it; that call records its own deletion alert.
  for category, outcome, rows, reason in
    select d.category, d.outcome, d.rows, d.reason
      from agni_delete_device_data(p_device_subject, p_contributors, p_subscription_subject) d
     where d.outcome = 'deleted'
  loop
    return next;
    counts := counts || jsonb_build_object(category, rows);
  end loop;

  delete from agni_usage_events e where e.subject_id = p_subscription_subject and e.status <> 'reserved';
  get diagnostics n = row_count;
  category := 'subscription_usage_events_all_devices'; outcome := 'deleted'; rows := n; reason := null; return next;
  counts := counts || jsonb_build_object('subscription_usage_events_all_devices', n);

  delete from agni_actions a
   where a.subject_id = p_subscription_subject
     and a.period_start not in (select p.period_start from agni_allowance_periods p
                                 where p.subject_id = p_subscription_subject and p.period_end > now());
  get diagnostics n = row_count;
  category := 'subscription_past_actions_all_devices'; outcome := 'deleted'; rows := n; reason := null; return next;
  counts := counts || jsonb_build_object('subscription_past_actions_all_devices', n);

  delete from agni_allowance_periods p where p.subject_id = p_subscription_subject and p.period_end <= now();
  get diagnostics n = row_count;
  category := 'subscription_past_allowance_periods'; outcome := 'deleted'; rows := n; reason := null; return next;
  counts := counts || jsonb_build_object('subscription_past_allowance_periods', n);

  delete from agni_subject_days d where d.subject_id = p_subscription_subject and d.day < today;
  get diagnostics n = row_count;
  category := 'subscription_past_daily_counts'; outcome := 'deleted'; rows := n; reason := null; return next;
  counts := counts || jsonb_build_object('subscription_past_daily_counts', n);

  -- Kept ---------------------------------------------------------------------

  select count(*) into n from agni_allowance_periods p
   where p.period_end > now() and p.subject_id in (p_subscription_subject, p_device_subject);
  category := 'current_allowance_counters'; outcome := 'kept'; rows := n;
  reason := 'Counts for this period only. Deleting them would reset your AI allowance.'; return next;

  select count(*) into n from agni_subject_days d
   where d.day = today and d.subject_id in (p_subscription_subject, p_device_subject);
  category := 'todays_counts'; outcome := 'kept'; rows := n;
  reason := 'Today''s photo count. Deleting it would reset the daily photo limit.'; return next;

  select count(*) into n from agni_actions a
   where a.subject_id in (p_subscription_subject, p_device_subject)
     and a.period_start in (select p.period_start from agni_allowance_periods p
                             where p.subject_id = a.subject_id and p.period_end > now());
  category := 'current_period_requests'; outcome := 'kept'; rows := n;
  reason := 'This period''s request ids. They stop a retried photo being charged twice.'; return next;

  select s.original_transaction_id into otid from agni_subjects s where s.subject_id = p_subscription_subject;
  category := 'subscription_purchase_record'; outcome := 'kept'; rows := 1;
  reason := 'Apple''s purchase record for your subscription. Needed to restore it and to apply refunds. Never your name, email or payment details.'; return next;

  select count(*) into n from agni_store_notifications sn where sn.original_transaction_id = otid;
  category := 'app_store_notices'; outcome := 'kept'; rows := n;
  reason := 'Apple''s notices of renewals, cancellations and refunds for this subscription, kept for the same reason.'; return next;

  select count(*) into n from agni_key_links l
   where l.subscription_subject = p_subscription_subject and l.device_subject <> p_device_subject;
  category := 'other_devices_links'; outcome := 'kept'; rows := n;
  reason := 'Your other devices'' link to the subscription. Removing it would switch Pro off on them.'; return next;

  select count(*) into n from agni_subjects d
   where d.subject_id = p_device_subject and (d.free_photo_exhausted or d.free_search_exhausted);
  category := 'free_sample_used_marker'; outcome := 'kept'; rows := n;
  reason := 'Records that this phone has used its free AI sample, so deleting cannot hand out another.'; return next;

  perform agni__deletion_alert('subscription', counts);
end;
$$;


-- ===== schema-retention.sql =====
-- Retention: how long each server record is kept, and the one function that
-- enforces it. PREPARED 2026-10-31, NOT YET APPLIED TO PRODUCTION AND NOT
-- SCHEDULED. Run after schema-billing.sql and before schema-lockdown.sql.
--
-- Until this runs on a schedule, nothing below is a promise: the privacy
-- policy must not quote these periods before it does. docs/retention.md has
-- the reasoning per table and the scheduling and backup notes.
--
-- TWO KINDS OF RECORD, kept for different reasons:
--
--   OPERATIONAL: usage events, actions, per-day counters, allowance periods,
--   caches, aggregate telemetry, alerts. Kept only as long as the code reads
--   them, plus a margin for support questions and Apple's refund window.
--
--   PURCHASE, RESTORATION, REFUND AND FRAUD: subscription subjects, key links,
--   attest keys, store notifications, device subjects. A subscription subject
--   is kept 400 days after it last ended so a late refund or chargeback still
--   finds it; a restore after that simply recreates it from Apple's signed
--   transaction. Device subjects, key links and attest keys are NOT deleted
--   here: deleting an attest key makes that phone's next request fail with
--   "key is not registered", and the app's recovery from that has not been
--   verified on a device. They wait for that check (docs/retention.md).
--
-- DRY RUN BY DEFAULT. agni_retention_cleanup() only counts; pass false to
-- delete. Every count is returned either way, so a scheduled run leaves a
-- record of what it removed.

create or replace function agni_retention_cleanup(p_dry_run boolean default true)
returns table (record text, rows bigint)
language plpgsql
security definer
as $$
declare
  n bigint;
  -- One place to read every period from.
  usage_days      constant interval := interval '180 days';
  subject_day_keep constant interval := interval '35 days';
  period_keep     constant interval := interval '180 days';
  telemetry_keep  constant interval := interval '400 days';
  budget_keep     constant interval := interval '730 days';
  variant_keep    constant interval := interval '180 days';
  ended_sub_keep  constant interval := interval '400 days';
begin
  -- Usage events: settled or expired only. A row still 'reserved' belongs to
  -- a call in flight or one the stale-reservation sweep has not closed yet.
  select count(*) into n from agni_usage_events
   where status <> 'reserved' and created_at < now() - usage_days;
  if not p_dry_run then
    delete from agni_usage_events where status <> 'reserved' and created_at < now() - usage_days;
  end if;
  record := 'agni_usage_events'; rows := n; return next;

  select count(*) into n from agni_actions where created_at < now() - usage_days;
  if not p_dry_run then delete from agni_actions where created_at < now() - usage_days; end if;
  record := 'agni_actions'; rows := n; return next;

  -- Per-day counters: only today is ever read (the daily photo limit).
  select count(*) into n from agni_subject_days where day < (now() - subject_day_keep)::date;
  if not p_dry_run then delete from agni_subject_days where day < (now() - subject_day_keep)::date; end if;
  record := 'agni_subject_days'; rows := n; return next;

  -- Allowance periods: the current one, and the previous one as a carry
  -- source (agni__carry_source looks back less than a month).
  select count(*) into n from agni_allowance_periods
   where period_end <> 'infinity' and period_end < now() - period_keep;
  if not p_dry_run then
    delete from agni_allowance_periods where period_end <> 'infinity' and period_end < now() - period_keep;
  end if;
  record := 'agni_allowance_periods'; rows := n; return next;

  -- Aggregates with no identifier of anybody.
  select count(*) into n from agni_auth_events where day < (now() - telemetry_keep)::date;
  if not p_dry_run then delete from agni_auth_events where day < (now() - telemetry_keep)::date; end if;
  record := 'agni_auth_events'; rows := n; return next;

  select count(*) into n from agni_alerts where at < now() - telemetry_keep;
  if not p_dry_run then delete from agni_alerts where at < now() - telemetry_keep; end if;
  record := 'agni_alerts'; rows := n; return next;

  -- The day's ceiling grows from the latest earlier row, so the newest row is
  -- always kept whatever its age.
  select count(*) into n from agni_budget_days
   where day < (now() - budget_keep)::date
     and day < (select max(day) from agni_budget_days);
  if not p_dry_run then
    delete from agni_budget_days
     where day < (now() - budget_keep)::date
       and day < (select max(day) from agni_budget_days);
  end if;
  record := 'agni_budget_days'; rows := n; return next;

  -- Redelivery dedupe needs days; a year covers an annual renewal cycle for
  -- anyone reconciling a refund.
  select count(*) into n from agni_store_notifications where received_at < now() - telemetry_keep;
  if not p_dry_run then delete from agni_store_notifications where received_at < now() - telemetry_keep; end if;
  record := 'agni_store_notifications'; rows := n; return next;

  -- Caches. Research and ingredient rows carry their own expiry and are never
  -- read past it; variant rows have no expiry column at all.
  select count(*) into n from agni_research_cache where expires_at < now();
  if not p_dry_run then delete from agni_research_cache where expires_at < now(); end if;
  record := 'agni_research_cache'; rows := n; return next;

  select count(*) into n from agni_ingredient_evidence where expires_at < now();
  if not p_dry_run then delete from agni_ingredient_evidence where expires_at < now(); end if;
  record := 'agni_ingredient_evidence'; rows := n; return next;

  select count(*) into n from agni_variant_cache where created_at < now() - variant_keep;
  if not p_dry_run then delete from agni_variant_cache where created_at < now() - variant_keep; end if;
  record := 'agni_variant_cache'; rows := n; return next;

  -- Already swept on use; here too so a quiet week still clears them.
  select count(*) into n from agni_attest_challenges where issued_at < now() - interval '1 day';
  if not p_dry_run then delete from agni_attest_challenges where issued_at < now() - interval '1 day'; end if;
  record := 'agni_attest_challenges'; rows := n; return next;

  select count(*) into n from agni_ip_windows where window_start < now() - interval '1 day';
  if not p_dry_run then delete from agni_ip_windows where window_start < now() - interval '1 day'; end if;
  record := 'agni_ip_windows'; rows := n; return next;

  -- Subscriptions that ended (expired past any grace, or revoked) more than
  -- 400 days ago. Their links are cleared first (the device keeps its link
  -- row), then their periods, then the subject. A restore recreates it.
  create temporary table if not exists retention_ended_subs (subject_id text primary key) on commit drop;
  truncate retention_ended_subs;
  insert into retention_ended_subs
    select subject_id from agni_subjects
     where kind = 'subscription'
       and coalesce(revocation_date,
                    greatest(expires_date, coalesce(grace_expires_date, expires_date))) < now() - ended_sub_keep;
  select count(*) into n from retention_ended_subs;
  if not p_dry_run then
    update agni_key_links set subscription_subject = null, subscription_linked_at = null
     where subscription_subject in (select subject_id from retention_ended_subs);
    delete from agni_allowance_periods where subject_id in (select subject_id from retention_ended_subs);
    delete from agni_subjects where subject_id in (select subject_id from retention_ended_subs);
  end if;
  record := 'agni_subjects (ended subscriptions)'; rows := n; return next;
end;
$$;

-- MARK: - Beta invitation emails

-- The TestFlight sign-up form kept an email address and name (agni_beta_signups).
-- Proposed: delete them 90 days after launch, or earlier on a verified request.
-- A verified request is handled by hand: the person writes from that address,
-- which is the proof they own it, and the row is deleted. This function only
-- covers the time rule. DRY RUN BY DEFAULT; nothing happens before
-- launch + 90 days whatever the dry-run flag says.
create or replace function agni_beta_signup_cleanup(p_launch_date date, p_dry_run boolean default true)
returns bigint
language plpgsql
security definer
as $$
declare
  n bigint;
begin
  if p_launch_date is null or current_date < p_launch_date + 90 then
    return 0;
  end if;
  select count(*) into n from agni_beta_signups where created_at < now() - interval '90 days';
  if not p_dry_run then
    delete from agni_beta_signups where created_at < now() - interval '90 days';
  end if;
  return n;
end;
$$;



-- ===== schema-contributor-migration.sql =====
-- One-off: convert the raw install ids already stored in agni_dish_submissions
-- and agni_dish_misses to the contributor hash new rows get (contributorId in
-- api/_lib.js). PREPARED 2026-10-31. Applying this file changes no data; it
-- only creates the tables and functions the conversion uses.
--
-- WHY IT IS SPLIT THIS WAY. The hash is keyed on a server secret
-- (CONTRIBUTOR_SALT or IP_HASH_SALT). The first draft of this cleanup was a SQL
-- script with the secret pasted into it, which would have put the secret in an
-- editor, its history and possibly a file. Here the secret never leaves the
-- Vercel runtime: the admin op in api/_contrib-migration.js reads the raw ids,
-- computes each hash in Node, and hands this SQL a map of raw id to hash. The
-- database never sees the secret, only the values it produces.
--
-- WHAT THE HASH IS AND IS NOT. It is pseudonymous, not anonymous. The server
-- can recompute it from any install id it is given, so a row stays linkable to
-- a phone by anyone holding the secret and the id. What it removes is the raw
-- install id stored beside dish data, which is also the key of that phone's
-- usage records (`dev:<install id>`), so the tables cannot be joined by a plain
-- equality without the secret.
--
-- Runbook: migrations/README.md. Apply after schema-misses.sql and
-- schema-community.sql, then run schema-lockdown.sql LAST, so the new tables
-- are closed to anon and the functions are service-role only.

-- Every row the conversion changes or deletes, as it was, so the conversion
-- can be undone exactly. Holds raw install ids: drop it once the conversion
-- is verified (the runbook says when).
create table if not exists agni_dish_contrib_backup_20261031 (
  row_key        text        primary key,   -- tbl|key|kind|install_id, as it was
  tbl            text        not null,      -- 'submissions' or 'misses'
  raw_install_id text        not null,      -- the raw id whose conversion touched this row
  hashed         text        not null,      -- what that raw id converts to
  snapshot       jsonb       not null,      -- the whole row before the change
  backed_up_at   timestamptz not null default now()
);
alter table agni_dish_contrib_backup_20261031 enable row level security;

-- Distinct contributors per dish before the conversion, counting a phone's raw
-- row and its newer hashed row as one phone. The conversion must leave every
-- one of these unchanged; verify compares.
create table if not exists agni_dish_contrib_counts_20261031 (
  tbl                 text not null,
  key                 text not null,
  kind                text not null,          -- '' for submissions, which have no kind
  contributors_before int  not null,
  primary key (tbl, key, kind)
);
alter table agni_dish_contrib_counts_20261031 enable row level security;

-- The map the admin op passes in: [{ "raw": "...", "hashed": "c1:..." }].
-- Anything that is not a well-formed pair stops the call, so a bug on the
-- Node side cannot write a malformed contributor.
create or replace function agni__contrib_map(p_map jsonb)
returns table (raw text, hashed text)
language plpgsql
stable
as $$
begin
  if p_map is null or jsonb_typeof(p_map) <> 'array' then
    raise exception 'contributor map must be a JSON array';
  end if;
  if exists (
    select 1 from jsonb_to_recordset(p_map) as x(raw text, hashed text)
     where x.raw is null or length(x.raw) < 8 or x.raw like 'c1:%'
        or x.hashed is null or x.hashed !~ '^c1:[0-9a-f]{32}$'
  ) then
    raise exception 'contributor map has a malformed entry';
  end if;
  return query select x.raw, x.hashed from jsonb_to_recordset(p_map) as x(raw text, hashed text);
end;
$$;

-- Distinct raw ids still stored, a page at a time (keyset on the id).
create or replace function agni_contrib_raw_ids(p_after text default '', p_limit int default 1000)
returns setof text
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select id from (
    select install_id as id from agni_dish_submissions where install_id not like 'c1:%'
    union
    select install_id from agni_dish_misses where install_id not like 'c1:%'
  ) ids
  where id > coalesce(p_after, '')
  order by id
  limit greatest(1, least(coalesce(p_limit, 1000), 5000));
$$;

-- Read only. How many rows the map would convert, and how many raw rows
-- already have a hashed twin from the same phone (written after the server
-- change was deployed) and would be merged into it instead.
create or replace function agni_contrib_preview(p_map jsonb)
returns table (tbl text, raw_rows int, merges int)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  with m as (select * from agni__contrib_map(p_map))
  select 'submissions',
         count(*)::int,
         count(*) filter (where exists (
           select 1 from agni_dish_submissions t where t.key = s.key and t.install_id = m.hashed))::int
    from agni_dish_submissions s join m on s.install_id = m.raw
  union all
  select 'misses',
         count(*)::int,
         count(*) filter (where exists (
           select 1 from agni_dish_misses t
            where t.key = d.key and t.kind = d.kind and t.install_id = m.hashed))::int
    from agni_dish_misses d join m on d.install_id = m.raw;
$$;

-- Records distinct contributors per dish BEFORE anything changes. Takes the
-- FULL map (all raw ids), so a phone's raw and hashed rows count as one phone
-- whichever chunk later converts them. First write wins: re-running it after a
-- partial conversion cannot overwrite the true "before".
create or replace function agni_contrib_snapshot(p_map jsonb)
returns int
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_count int;
begin
  with m as (select * from agni__contrib_map(p_map)),
  touched as (
    select 'submissions'::text as tbl, s.key, ''::text as kind
      from agni_dish_submissions s join m on s.install_id = m.raw
    union
    select 'misses', d.key, d.kind
      from agni_dish_misses d join m on d.install_id = m.raw
  ),
  counted as (
    select t.tbl, t.key, t.kind,
           (select count(distinct coalesce(m2.hashed, s.install_id))
              from agni_dish_submissions s left join m m2 on m2.raw = s.install_id
             where t.tbl = 'submissions' and s.key = t.key)
         + (select count(distinct coalesce(m2.hashed, d.install_id))
              from agni_dish_misses d left join m m2 on m2.raw = d.install_id
             where t.tbl = 'misses' and d.key = t.key and d.kind = t.kind) as contributors
      from touched t
  )
  insert into agni_dish_contrib_counts_20261031 (tbl, key, kind, contributors_before)
  select tbl, key, kind, contributors from counted
  on conflict (tbl, key, kind) do nothing;
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

-- The conversion, for the ids in p_map, in ONE transaction (the call). Backs
-- up every row it will change or delete first; a backup that already exists
-- is kept, so the oldest state survives a re-run. Idempotent: ids already
-- converted have no raw rows left and touch nothing.
create or replace function agni_contrib_apply(p_map jsonb)
returns table (tbl text, backed_up int, merged int, converted int)
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  b_s int; b_m int; mg_s int; mg_m int; c_s int; c_m int;
begin
  create temporary table if not exists contrib_map (raw text primary key, hashed text not null) on commit drop;
  truncate contrib_map;
  insert into contrib_map select * from agni__contrib_map(p_map) on conflict do nothing;

  -- 1. Backup: the raw rows, and any hashed twin a merge would change.
  insert into agni_dish_contrib_backup_20261031 (row_key, tbl, raw_install_id, hashed, snapshot)
  select 'submissions|' || s.key || '||' || s.install_id, 'submissions', m.raw, m.hashed, to_jsonb(s)
    from agni_dish_submissions s join contrib_map m on s.install_id = m.raw
  union all
  select 'submissions|' || t.key || '||' || t.install_id, 'submissions', m.raw, m.hashed, to_jsonb(t)
    from agni_dish_submissions s join contrib_map m on s.install_id = m.raw
    join agni_dish_submissions t on t.key = s.key and t.install_id = m.hashed
  on conflict (row_key) do nothing;
  get diagnostics b_s = row_count;

  insert into agni_dish_contrib_backup_20261031 (row_key, tbl, raw_install_id, hashed, snapshot)
  select 'misses|' || d.key || '|' || d.kind || '|' || d.install_id, 'misses', m.raw, m.hashed, to_jsonb(d)
    from agni_dish_misses d join contrib_map m on d.install_id = m.raw
  union all
  select 'misses|' || t.key || '|' || t.kind || '|' || t.install_id, 'misses', m.raw, m.hashed, to_jsonb(t)
    from agni_dish_misses d join contrib_map m on d.install_id = m.raw
    join agni_dish_misses t on t.key = d.key and t.kind = d.kind and t.install_id = m.hashed
  on conflict (row_key) do nothing;
  get diagnostics b_m = row_count;

  -- 2. Merges. A raw submission with a hashed twin: the hashed row is newer
  --    (written after the deploy), so it wins and the raw row goes.
  delete from agni_dish_submissions s using contrib_map m, agni_dish_submissions t
   where s.install_id = m.raw and t.key = s.key and t.install_id = m.hashed;
  get diagnostics mg_s = row_count;

  -- A raw miss with a hashed twin: the phone's running total is the larger.
  update agni_dish_misses t set
    times = greatest(t.times, d.times),
    first_seen = least(t.first_seen, d.first_seen),
    last_seen = greatest(t.last_seen, d.last_seen)
    from agni_dish_misses d join contrib_map m on d.install_id = m.raw
   where t.key = d.key and t.kind = d.kind and t.install_id = m.hashed;
  delete from agni_dish_misses d using contrib_map m, agni_dish_misses t
   where d.install_id = m.raw and t.key = d.key and t.kind = d.kind and t.install_id = m.hashed;
  get diagnostics mg_m = row_count;

  -- 3. Everything else converts in place.
  update agni_dish_submissions s set install_id = m.hashed
    from contrib_map m where s.install_id = m.raw;
  get diagnostics c_s = row_count;
  update agni_dish_misses d set install_id = m.hashed
    from contrib_map m where d.install_id = m.raw;
  get diagnostics c_m = row_count;

  return query values ('submissions'::text, b_s, mg_s, c_s), ('misses'::text, b_m, mg_m, c_m);
end;
$$;

-- Read only. Zero raw rows left, and no dish whose distinct-contributor count
-- moved from the snapshot. A non-zero changed_counts means STOP and roll back.
create or replace function agni_contrib_verify()
returns table (check_name text, value int)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select 'raw_submissions_left', (select count(*)::int from agni_dish_submissions where install_id not like 'c1:%')
  union all
  select 'raw_misses_left', (select count(*)::int from agni_dish_misses where install_id not like 'c1:%')
  union all
  select 'changed_counts', (
    select count(*)::int from agni_dish_contrib_counts_20261031 c
     where c.contributors_before <> case c.tbl
       when 'submissions' then (select count(distinct install_id) from agni_dish_submissions s where s.key = c.key)
       else (select count(distinct install_id) from agni_dish_misses d where d.key = c.key and d.kind = c.kind)
     end)
  union all
  select 'backup_rows', (select count(*)::int from agni_dish_contrib_backup_20261031)
  union all
  select 'snapshot_dishes', (select count(*)::int from agni_dish_contrib_counts_20261031);
$$;

-- Puts every backed-up row back exactly as it was: removes the converted and
-- merged rows for each backed-up identity, then re-inserts the snapshots.
-- Leaves the backup in place, so the conversion can be applied again. A row
-- the same phone wrote for the same dish AFTER the conversion is replaced by
-- the snapshot; roll back soon or not at all.
create or replace function agni_contrib_rollback()
returns table (tbl text, removed int, restored int)
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  r_s int; r_m int; i_s int; i_m int;
begin
  delete from agni_dish_submissions s using agni_dish_contrib_backup_20261031 b
   where b.tbl = 'submissions' and s.key = b.snapshot->>'key'
     and s.install_id in (b.hashed, b.raw_install_id);
  get diagnostics r_s = row_count;
  delete from agni_dish_misses d using agni_dish_contrib_backup_20261031 b
   where b.tbl = 'misses' and d.key = b.snapshot->>'key' and d.kind = b.snapshot->>'kind'
     and d.install_id in (b.hashed, b.raw_install_id);
  get diagnostics r_m = row_count;

  insert into agni_dish_submissions
  select (jsonb_populate_record(null::agni_dish_submissions, b.snapshot)).*
    from agni_dish_contrib_backup_20261031 b where b.tbl = 'submissions';
  get diagnostics i_s = row_count;
  insert into agni_dish_misses
  select (jsonb_populate_record(null::agni_dish_misses, b.snapshot)).*
    from agni_dish_contrib_backup_20261031 b where b.tbl = 'misses';
  get diagnostics i_m = row_count;

  return query values ('submissions'::text, r_s, i_s), ('misses'::text, r_m, i_m);
end;
$$;


-- ===== schema-dish-cleanup.sql =====
-- Removing self-test dishes from the shared dish table. PREPARED 2026-10-31,
-- NOT APPLIED TO PRODUCTION, NOT RUN. Run after schema-community.sql and before
-- schema-lockdown.sql. Driven by POST /api/quota?op=test-dish-cleanup
-- (api/_dish-cleanup.js); proposal and evidence in
-- docs/readonly-queries/test-dish-cleanup-proposal.md.
--
-- EXACT ROWS ONLY. Every function takes an explicit list of (key, install_id)
-- pairs and matches them by equality: no wildcard, no pattern, no dish name.
-- Node expands each pair to both forms a row may hold (the raw install id and
-- its c1: contributor hash), so the list works before or after the
-- contributor conversion. The salt never comes here.
--
-- PUBLICATION is what agni_community_dishes decides: a key is offered to
-- people once it has at least two submission rows.
--
-- BACKUP. apply copies every row it will delete into
-- agni_dish_cleanup_backup_20261031 in the same transaction. rollback puts
-- them back. Drop the table 7 days after a clean verify (runbook in the
-- proposal); until then it holds contributor values, so it is locked down like
-- every agni table.

create table if not exists agni_dish_cleanup_backup_20261031 (
  key             text        not null,
  name            text        not null,
  install_id      text        not null,
  unit            text        not null,
  grams_per_unit  numeric,
  kcal            numeric,
  protein_g       numeric,
  carbs_g         numeric,
  fat_g           numeric,
  created_at      timestamptz,
  updated_at      timestamptz,
  backed_up_at    timestamptz not null default now(),
  primary key (key, install_id)
);
alter table agni_dish_cleanup_backup_20261031 enable row level security;

create or replace function agni__dish_pairs(p_pairs jsonb)
returns table (key text, install_id text)
language sql
immutable
as $$
  select distinct p->>'key', p->>'install_id'
    from jsonb_array_elements(coalesce(p_pairs, '[]'::jsonb)) p
   where coalesce(p->>'key', '') <> '' and length(coalesce(p->>'install_id', '')) >= 8;
$$;

-- What would happen, per key: rows matched, contributors now and after, and
-- whether the key is offered to people now and after. No install id returned.
create or replace function agni_dish_cleanup_preview(p_pairs jsonb)
returns table (key text, matched integer, contributors_now integer, contributors_after integer,
               published_now boolean, published_after boolean)
language sql
security definer
as $$
  with pairs as (select * from agni__dish_pairs(p_pairs)),
  hit as (
    select s.key, count(*)::int as matched
      from agni_dish_submissions s join pairs p on p.key = s.key and p.install_id = s.install_id
     group by s.key
  ),
  totals as (
    select s.key, count(*)::int as n from agni_dish_submissions s where s.key in (select h.key from hit h) group by s.key
  )
  select h.key, h.matched, t.n, t.n - h.matched, t.n >= 2, (t.n - h.matched) >= 2
    from hit h join totals t using (key)
   order by h.key;
$$;

create or replace function agni_dish_cleanup_apply(p_pairs jsonb)
returns table (backed_up bigint, deleted bigint, keys_unpublished bigint)
language plpgsql
security definer
as $$
declare
  b bigint;
  d bigint;
  u bigint;
  published_before text[];
begin
  select coalesce(array_agg(c.key), '{}') into published_before
    from (select s.key from agni_dish_submissions s
           where s.key in (select key from agni__dish_pairs(p_pairs))
           group by s.key having count(*) >= 2) c;

  insert into agni_dish_cleanup_backup_20261031
    (key, name, install_id, unit, grams_per_unit, kcal, protein_g, carbs_g, fat_g, created_at, updated_at)
  select s.key, s.name, s.install_id, s.unit, s.grams_per_unit, s.kcal, s.protein_g, s.carbs_g, s.fat_g,
         s.created_at, s.updated_at
    from agni_dish_submissions s
    join agni__dish_pairs(p_pairs) p on p.key = s.key and p.install_id = s.install_id
  on conflict (key, install_id) do nothing;
  get diagnostics b = row_count;

  delete from agni_dish_submissions s
   using agni__dish_pairs(p_pairs) p
   where p.key = s.key and p.install_id = s.install_id;
  get diagnostics d = row_count;

  select count(*) into u from unnest(published_before) k
   where (select count(*) from agni_dish_submissions s where s.key = k) < 2;

  return query select b, d, u;
end;
$$;

-- After apply: matched rows still present (must be 0), backup size, and the
-- keys that are no longer offered to people.
create or replace function agni_dish_cleanup_verify(p_pairs jsonb)
returns table (remaining bigint, in_backup bigint, unpublished_keys text[])
language sql
security definer
as $$
  select
    (select count(*) from agni_dish_submissions s
       join agni__dish_pairs(p_pairs) p on p.key = s.key and p.install_id = s.install_id),
    (select count(*) from agni_dish_cleanup_backup_20261031),
    (select coalesce(array_agg(distinct b.key order by b.key), '{}')
       from agni_dish_cleanup_backup_20261031 b
      where (select count(*) from agni_dish_submissions s where s.key = b.key) < 2);
$$;

-- Puts every backed-up row back. A row someone has since re-submitted is left
-- as they wrote it.
create or replace function agni_dish_cleanup_rollback()
returns bigint
language plpgsql
security definer
as $$
declare
  n bigint;
begin
  insert into agni_dish_submissions
    (key, name, install_id, unit, grams_per_unit, kcal, protein_g, carbs_g, fat_g, created_at, updated_at)
  select key, name, install_id, unit, grams_per_unit, kcal, protein_g, carbs_g, fat_g, created_at, updated_at
    from agni_dish_cleanup_backup_20261031
  on conflict (key, install_id) do nothing;
  get diagnostics n = row_count;
  return n;
end;
$$;


-- ===== schema-lockdown.sql =====
-- Who may touch Agni's database. Run LAST, after every other schema file, and
-- again after any of them is re-run: `create or replace function` keeps grants,
-- but a dropped and re-created function picks Supabase's defaults back up.
--
-- WHY. Supabase grants EXECUTE on every new function in `public`, and ALL on
-- every new table and view, to the anon and authenticated roles, and exposes
-- them over its REST API. Agni's server is the only intended caller and uses
-- the service role. Audited 2026-10-08 against a database that reproduces
-- those defaults, anon could:
--
--   * agni_attest_register: register a public key of its own under any key id,
--     then sign assertions with it. That is App Attest bypassed outright, and
--     it overwrites a real device's key when the id is known.
--   * agni_attest_gate / agni_attest_gate_class: pass a NEGATIVE previous cost
--     and walk a key's daily spend, and the service-wide day spend, back to
--     zero (a $40 day was reset to $0 in the probe), or burn a device's
--     replay counter and call windows.
--   * agni_attest_spend_free, agni_attest_claim, agni_attest_begin,
--     agni_attest_issue, agni_attest_advance: spend other keys' free
--     allowance, burn challenges, fill the challenge table.
--   * agni_check / agni_consume: create and spend legacy install counters.
--   * agni_cache_variants, agni_ingredient_evidence_put, agni_submit_dish,
--     agni_report_miss: write nutrition data every user is later served.
--   * agni_ingredient_evidence: read and write the TABLE directly (it was the
--     one table without row level security).
--   * agni_auth_summary, agni_beta_list: read telemetry and testers' emails.
--
-- None of this needs a stolen secret beyond the anon key, which Supabase calls
-- public and which is not in the app or the server today. "Not distributed" is
-- not a control, so this file removes the access rather than relying on it.
--
-- WHAT IT DOES, for every object named agni*, so a function added later is
-- covered the next time this runs (and the test fails until it does):
--   1. functions: EXECUTE revoked from public, anon and authenticated, granted
--      to service_role; security definer ones pinned to search_path public.
--   2. tables and views: everything revoked from anon and authenticated.
--   3. row level security on, everywhere.
--   4. views run as the caller (security_invoker), so they cannot be used to
--      read past row level security.
--
-- WHAT IT DOES NOT CHANGE: the service role, which the server uses, keeps
-- every privilege it had. Nothing the server calls loses access.

alter table if exists agni_ingredient_evidence enable row level security;

do $$
declare
  f record;
  t record;
begin
  for f in
    select p.oid::regprocedure as sig, p.prosecdef as definer
      from pg_proc p join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public' and p.proname like 'agni%'
  loop
    execute format('revoke execute on function %s from public', f.sig);
    if exists (select 1 from pg_roles where rolname = 'anon') then
      execute format('revoke execute on function %s from anon', f.sig);
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
      execute format('revoke execute on function %s from authenticated', f.sig);
    end if;
    if exists (select 1 from pg_roles where rolname = 'service_role') then
      execute format('grant execute on function %s to service_role', f.sig);
    end if;
    if f.definer then
      execute format('alter function %s set search_path = public, pg_temp', f.sig);
    end if;
  end loop;

  for t in
    select c.oid::regclass as rel, c.relkind
      from pg_class c join pg_namespace n on n.oid = c.relnamespace
     where n.nspname = 'public' and c.relname like 'agni%' and c.relkind in ('r', 'v', 'm', 'p')
  loop
    if exists (select 1 from pg_roles where rolname = 'anon') then
      execute format('revoke all on %s from anon', t.rel);
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
      execute format('revoke all on %s from authenticated', t.rel);
    end if;
    if t.relkind in ('r', 'p') then
      execute format('alter table %s enable row level security', t.rel);
    elsif t.relkind = 'v' then
      execute format('alter view %s set (security_invoker = true)', t.rel);
    end if;
  end loop;
end;
$$;


commit;
